return ['domain'=>'blockstudio','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'hi_IN','project-id-version'=>'Blockstudio','po-revision-date'=>'2026-10-23 15:31+0000','messages'=>['Blockstudio'=>'Blockstudio','The "%1$s" attribute on a %2$s block tag is dropped because the block declares no field with that id. Declare the field, or write it as a data-, aria- or html- attribute to put it on the root element.'=>'%2$s ब्लॉक टैग पर "%1$s" एट्रिब्यूट हटाया गया है, क्योंकि ब्लॉक में उस ID वाला कोई फ़ील्ड घोषित नहीं है। फ़ील्ड घोषित करें या इसे data-, aria- या html- एट्रिब्यूट के रूप में लिखें, ताकि यह रूट एलिमेंट पर जुड़ जाए।','This storage key is not declared by the block or its extensions.'=>'यह स्टोरेज कुंजी ब्लॉक या उसके एक्सटेंशन में घोषित नहीं है।','This top-level key is not an attribute of the block, so it is ignored.'=>'यह शीर्ष-स्तरीय कुंजी ब्लॉक का गुण नहीं है, इसलिए इसे अनदेखा किया जाता है।','This key is only read inside the blockstudio object, which is missing.'=>'यह कुंजी केवल blockstudio ऑब्जेक्ट के अंदर पढ़ी जाती है, जो मौजूद नहीं है।','This value is not among the field options.'=>'यह मान फ़ील्ड के विकल्पों में शामिल नहीं है।','This value has an unsupported shape for the field.'=>'इस फ़ील्ड के लिए इस मान का फ़ॉर्मैट समर्थित नहीं है।','This repeater has fewer rows than its minimum.'=>'इस रिपीटर में न्यूनतम से कम पंक्तियाँ हैं।','This repeater has more rows than its maximum.'=>'इस रिपीटर में अधिकतम से ज़्यादा पंक्तियाँ हैं।','This storage key has conflicting field definitions.'=>'इस स्टोरेज कुंजी के लिए फ़ील्ड परिभाषाएँ परस्पर विरोधी हैं।','The nested field value overrides this top-level value.'=>'नेस्टेड फ़ील्ड का मान इस शीर्ष-स्तरीय मान को अधिलेखित करता है।','Extension bindings read this value only from blockstudio.attributes.'=>'एक्सटेंशन बाइंडिंग यह मान केवल blockstudio.attributes से पढ़ती हैं।','Blockstudio field values must be stored in an object.'=>'Blockstudio फ़ील्ड के मान किसी ऑब्जेक्ट में संग्रहीत होने चाहिए।','Blockstudio is preparing it